def w(name, body): open(name,"w").write(body)
# cyclomatic complexity sweep: N sequential ifs in one function
for n in (5,8,9,10,12,15,20):
    body="def f(x):\n"+"".join(f"    if x == {i}:\n        x += {i}\n" for i in range(n))+"    return x\n"
    w(f"cc_{n}.py", body)
# argument count sweep
for n in (3,4,5,6,7,8):
    args=", ".join(f"a{i}" for i in range(n))
    w(f"args_{n}.py", f"def f({args}):\n    return {args.split(', ')[0]}\n")
# function length sweep (straight-line statements)
for n in (40,60,70,80,100,120):
    w(f"len_{n}.py","def f():\n    x = 0\n"+"".join(f"    x += {i}\n" for i in range(n))+"    return x\n")
# nesting depth sweep
for d in (2,3,4,5):
    body="def f(x):\n"; ind="    "
    for i in range(d):
        body+=f"{ind}if x > {i}:\n"; ind+="    "
