"""The archy-side detectors for #870, pinned to what `cs review` did in calibration.

Every expectation here was observed from the CodeScene CLI on the same source
on 2026-11-09 and is recorded in
``docs/research/HEALTH_REPRODUCIBILITY_PREREG.md``. A test failing means the
detector drifted from the tool it is being compared with, which would quietly
change the experiment.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

# bench/ is appended, never prepended, so a bench module cannot shadow stdlib
# or installed imports, mirroring tests/test_q1b_run.py.
sys.path.append(str(Path(__file__).resolve().parent.parent / "bench"))

import health_repro as hr  # ty: ignore[unresolved-import]  (added to sys.path above)

COMPLEX = "Complex Method"
ARGS = "Excess Number of Function Arguments"
LARGE = "Large Method"
NEST = "Deep, Nested Complexity"
COND = "Complex Conditional"


def flagged(source: str, smell: str) -> set[str]:
    return {name for name, _ in hr.smells_in_source(source)[smell]}


def ifs(n: int) -> str:
    body = "".join(f"    if x == {i}:\n        x += {i}\n" for i in range(n))
    return f"def f(x):\n{body}    return x\n"


def test_cyclomatic_nine_is_flagged_and_eight_branches_below_it_is_not():
    # Eight sequential ifs is cyclomatic 9; five is 6. Observed: cs flags 8, not 5.
    assert flagged(ifs(8), COMPLEX) == {"f"}
    assert flagged(ifs(5), COMPLEX) == set()


def test_self_and_cls_are_not_counted_as_arguments():
    four = "class C:\n    def m(self, a, b, c, d):\n        return a\n"
    five = "class C:\n    def m(self, a, b, c, d, e):\n        return a\n"
    classm = "class C:\n    @classmethod\n    def m(cls, a, b, c, d):\n        return a\n"
    assert flagged(four, ARGS) == set()
    assert flagged(five, ARGS) == {"m"}
    assert flagged(classm, ARGS) == set()


def test_star_and_keyword_only_arguments_are_counted():
    star = "def f(a, b, c, *args, **kwargs):\n    return a\n"
    kwonly = "def f(a, b, *, c, d, e):\n    return a\n"
    assert flagged(star, ARGS) == {"f"}
    assert flagged(kwonly, ARGS) == {"f"}


def test_a_plain_function_named_self_first_parameter_is_still_counted():
    # `self` is dropped only for methods; a free function's first parameter is real.
    free = "def f(self, a, b, c, d):\n    return a\n"
    assert flagged(free, ARGS) == {"f"}


def test_a_function_nested_in_a_function_is_not_checked():
    nested = "def outer(a):\n    def inner(a, b, c, d, e):\n        return a\n    return inner\n"
    assert flagged(nested, ARGS) == set()


def test_blank_and_comment_lines_do_not_count_toward_method_length():
    blanks = (
        "def f():\n    x = 0\n" + "".join(f"    x += {i}\n\n" for i in range(40)) + "    return x\n"
    )
    comments = (
        "def f():\n    x = 0\n"
        + "".join(f"    # c{i}\n    x += {i}\n" for i in range(40))
        + "    return x\n"
    )
    # Both have 42 code lines but 82 physical lines: the fixture reaches the branch.
    assert len(blanks.splitlines()) > hr.MAX_CODE_LINES
    assert len(comments.splitlines()) > hr.MAX_CODE_LINES
    assert flagged(blanks, LARGE) == set()
    assert flagged(comments, LARGE) == set()


def test_docstring_lines_count_toward_method_length():
    doc = "\n".join(f"doc line {i}" for i in range(70))
    source = f'def f():\n    """{doc}"""\n    return 1\n'
    assert flagged(source, LARGE) == {"f"}


def test_four_nested_loops_or_ifs_are_flagged_and_three_are_not():
    four = (
        "def f(xs):\n    for a in xs:\n        for b in xs:\n            for c in xs:\n"
        "                for d in xs:\n                    print(d)\n"
    )
    three = (
        "def f(xs):\n    for a in xs:\n        for b in xs:\n            for c in xs:\n"
        "                print(c)\n"
    )
    assert flagged(four, NEST) == {"f"}
    assert flagged(three, NEST) == set()


def test_with_and_try_do_not_add_nesting():
    source = (
        "def f(xs):\n    for a in xs:\n        while a:\n            with open(a) as h:\n"
        "                try:\n                    print(h)\n                except Exception:\n"
        "                    pass\n"
    )
    assert flagged(source, NEST) == set()


def test_an_elif_chain_is_not_nesting():
    chain = "def f(x):\n    if x == 0:\n        return 0\n"
    chain += "".join(f"    elif x == {i}:\n        return {i}\n" for i in range(1, 6))
    chain += "    return -1\n"
    # Six branches in the ast nest five Ifs deep through orelse; cs counts none.
    assert chain.count("elif") == 5
    assert flagged(chain, NEST) == set()


def test_an_if_under_else_is_real_nesting():
    # `else:` then `if` is a genuine extra level, unlike `elif`.
    source = (
        "def f(x):\n    if x == 0:\n        return 0\n    else:\n        if x == 1:\n"
        "            return 1\n        else:\n            if x == 2:\n                return 2\n"
        "            else:\n                if x == 3:\n                    return 3\n"
    )
    assert flagged(source, NEST) == {"f"}


def test_comprehension_filters_do_not_nest():
    source = "def f(xs):\n    return [a for a in xs if a if a > 1 if a > 2 if a > 3]\n"
    assert flagged(source, NEST) == set()


def test_two_boolean_operators_in_an_if_or_while_are_flagged():
    three_terms = "def f(a, b, c):\n    if a and b and c:\n        return 1\n    return 0\n"
    mixed = "def f(a, b, c):\n    if a and b or c:\n        return 1\n    return 0\n"
    loop = "def f(a, b, c):\n    while a and b and c:\n        a = 0\n"
    assert flagged(three_terms, COND) == {"f"}
    assert flagged(mixed, COND) == {"f"}
    assert flagged(loop, COND) == {"f"}


def test_one_operator_or_one_in_a_return_or_assignment_is_not_flagged():
    one = "def f(a, b):\n    if not a and not b:\n        return 1\n    return 0\n"
    ret = "def f(a, b, c):\n    return a and b and c\n"
    assign = "def f(a, b, c):\n    x = a and b and c\n    return x\n"
    assert flagged(one, COND) == set()
    assert flagged(ret, COND) == set()
    assert flagged(assign, COND) == set()


def test_a_finding_resolves_by_name_and_start_line_within_the_decorator_window():
    table = [("f", 10, 20), ("g", 30, 40)]
    assert hr._resolve(table, "f", 12, None) == ("f", 10)
    assert hr._resolve(table, "f", 14, None) is None  # outside the 3-line window
    assert hr._resolve(table, "nope", 10, None) is None  # a name that matched nothing


def test_a_conditional_finding_resolves_to_the_function_containing_its_line():
    # Complex Conditional is reported against the condition's line, not the def line.
    table = [("f", 10, 20), ("f", 50, 60)]
    assert hr._resolve(table, "f", None, 55) == ("f", 50)
    assert hr._resolve(table, "f", None, 35) is None


def test_cs_findings_that_resolve_to_nothing_are_listed_not_dropped():
    review = [
        {
            "path": "a.py",
            "score": 9.0,
            "review": [
                {
                    "category": COMPLEX,
                    "functions": [
                        {"title": "f", "start-line": 2},
                        {"title": "ghost", "start-line": 9},
                    ],
                }
            ],
        }
    ]
    result = hr.cs_flags(review, {"a.py": [("f", 2, 5)]})
    assert result["flags"]["a.py"][COMPLEX] == {("f", 2)}
    assert result["unresolved"] == [("a.py", COMPLEX, "ghost")]


def test_jaccard_is_worked_by_hand_and_undefined_for_two_empty_sets():
    # |a n b| = 2, |a u b| = 4, so 0.5. The 92-of-129 baseline in the prereg is 0.713.
    assert hr.jaccard({1, 2, 3}, {2, 3, 4}) == 0.5
    assert round(92 / (112 + 109 - 92), 3) == 0.713
    assert hr.jaccard(set(), set()) is None


def test_spearman_is_minus_one_for_a_reversed_order_and_handles_ties():
    assert hr.spearman([1, 2, 3, 4], [4, 3, 2, 1]) == -1.0
    assert hr.spearman([1, 2, 3, 4], [10, 20, 30, 40]) == 1.0
    # Average ranks for ties: x ranks 1.5, 1.5, 3; y ranks 1, 2, 3. rho = 0.866...
    assert round(hr.spearman([1, 1, 2], [1, 2, 3]) or 0, 3) == 0.866
    assert hr.spearman([1, 1, 1], [1, 2, 3]) is None  # no variance, no correlation
    assert hr.spearman([1, 2], [2, 1]) is None  # too few points to say


def test_only_ok_rows_count_as_done_so_a_stall_is_retried(tmp_path):
    ledger = tmp_path / "ledger.jsonl"
    rows = [
        {"project": "a", "status": "ok"},
        {"project": "b", "status": "stalled"},
        {"project": "c", "status": "error"},
    ]
    ledger.write_text("".join(json.dumps(r) + "\n" for r in rows), encoding="utf-8")
    assert hr._done(ledger) == {"a"}


def test_a_method_finding_titled_class_dot_method_resolves_to_the_method():
    # `cs` reports methods as `Class.method`, and a conditional as `Class.method:LINE`.
    review = [
        {
            "path": "a.py",
            "score": 9.0,
            "review": [
                {
                    "category": COMPLEX,
                    "functions": [{"title": "Editor.edit", "start-line": 4}],
                },
                {"category": COND, "functions": [{"title": "Editor.edit:7"}]},
            ],
        }
    ]
    result = hr.cs_flags(review, {"a.py": [("edit", 4, 9)]})
    assert result["unresolved"] == []
    assert result["flags"]["a.py"][COMPLEX] == {("edit", 4)}
    assert result["flags"]["a.py"][COND] == {("edit", 4)}

    findings: tuple[StrictFinding, ...] = ()
    carried_cycles: int = 0
    carried_violations: int = 0
    # Set when the baseline cannot support a verdict at all. A refused verdict
    # fails: a gate that cannot evaluate must not read as clean.
    refused: str | None = None
    # Set when the baseline predates the rules fingerprint. Not a failure.
    # The cycle and violation ratchet still runs; this only says how to record
    # rules so a later config edit cannot hide a finding.
    rules_hint: str | None = None

    @computed_field
    @property
    def passed(self) -> bool:
        return self.refused is None and not self.findings

    @computed_field
    @property
    def reason(self) -> str:
        if self.refused is not None:
            return f"strict diff refused against {self.baseline}: {self.refused}"
        carried = (
            f"{self.carried_cycles} cycle(s) and {self.carried_violations} violation(s) "
            f"carried from {self.baseline}"
        )
        if not self.findings:
            text = f"no new cycles or layer violations; {carried}"
        else:
            lines = [f"{len(self.findings)} new finding(s); {carried}:"]
            lines.extend(f"  {finding.detail}" for finding in self.findings)
            text = "\n".join(lines)
        if self.rules_hint:
            return f"{text}\n{self.rules_hint}"
        return text


def evaluate_strict(
    *,
    baseline_label: str,
    baseline_modules: tuple[str, ...],
    baseline_cycles: Iterable[Cycle],
    baseline_violations: Iterable[Violation],
    current_cycles: Iterable[Cycle],
    current_violations: Iterable[Violation],
    module_paths: Mapping[str, str],
    ungoverned: tuple[Violation, ...] | None,
    regenerate: str,
) -> StrictVerdict:
    """Compare current findings against a committed baseline.

    `module_paths` maps a module to the file path a reader should see (relative
    to the project when possible), for the `path:line` locations.
    """
    if not baseline_modules:
        return StrictVerdict(
            baseline=baseline_label,
            refused=(
                "the baseline records no module list (written before `--strict` "
                "existed, or from an empty scan), so a new file cannot be told from an "
                f"existing module. Regenerate it with `{regenerate}`."
            ),
        )
    baseline_violations = list(baseline_violations)
    # A baseline violation can only be carried or resolved by a rule that still
    # runs. With no archy.yaml, or a layer whose patterns now match nothing (a
    # bare `pkg.core` for `pkg.core.**`, a package renamed under the config),
    # the violation silently drops out and new ones go unseen: a rule set that
    # cannot fire reading as clean.
    if baseline_violations:
        remedy = (
            "Restore the rules, or if they were removed on purpose, regenerate the "
            f"baseline with `{regenerate}`."
        )
        if ungoverned is None:
            return StrictVerdict(
                baseline=baseline_label,
                refused=(
                    f"the baseline records {len(baseline_violations)} layer violation(s), "
                    "but no archy.yaml was found for this scan, so no layer rule was "
                    f"checked. {remedy}"
                ),
            )
        if ungoverned:
            first = ungoverned[0]
            return StrictVerdict(
                baseline=baseline_label,
                refused=(
                    f"the rules in archy.yaml no longer cover {len(ungoverned)} baseline "
                    f"violation(s) whose modules still exist (e.g. {first.source} -> "
                    f"{first.target}, {first.rule.from_layer} -> {first.rule.to_layer}), so "
                    f"those rules cannot fire. {remedy}"
                ),
            )
    known = set(baseline_modules)
    baseline_cycles = list(baseline_cycles)
    old_cycles = [set(c.modules) for c in baseline_cycles]
    old_cycle_edges = {(e.source, e.target) for c in baseline_cycles for e in c.edges}
    # Which baseline cycle each module sat in. An edge between two members of
    # the same one deepened a tangle the baseline already carries; it did not
    # close the new cycle, so naming it would send the reader to the wrong line.
    old_cycle_of = {m: i for i, members in enumerate(old_cycles) for m in members}

    def closes(source: str, target: str) -> bool:
        if (source, target) in old_cycle_edges:
            return False
        return old_cycle_of.get(source, -1) != old_cycle_of.get(target, -2)

    findings: list[StrictFinding] = []
    carried_cycles = 0
    for cycle in current_cycles:
        seen = set(cycle.modules) & known
        if len(cycle.modules) == 1:
            # A self-import is its own kind of cycle: carried only if the
            # baseline had that exact self-edge, not merely because the module
            # once sat in a larger cycle that has since been broken.
            [module] = cycle.modules
            carried = (module, module) in old_cycle_edges
        else:
            carried = bool(seen) and any(seen <= old for old in old_cycles)
        if carried:
            carried_cycles += 1
            continue
        closing = [e for e in cycle.edges if closes(e.source, e.target)]
        edges = tuple(
            StrictEdge(
                source=e.source,
                target=e.target,
                locations=_locations(module_paths.get(e.source), e.lines),
            )
            for e in sorted(closing or cycle.edges, key=lambda e: (e.source, e.target))
        )
        findings.append(
            StrictFinding(
                kind="cycle",
                modules=tuple(sorted(cycle.modules)),
                edges=edges,
                detail=_cycle_detail(cycle, seen, old_cycles, edges),
            )
        )

    old_violations = {_violation_key(v) for v in baseline_violations}
    carried_violations = 0
    for v in current_violations:
        if _violation_key(v) in old_violations:
            carried_violations += 1
            continue
        edge = StrictEdge(
            source=v.source,
            target=v.target,
            locations=_locations(module_paths.get(v.source), v.lines),
        )
        findings.append(
            StrictFinding(
                kind="violation",
                modules=(v.source, v.target),
                edges=(edge,),
                detail=(
                    f"new layer violation ({v.rule.from_layer} -> {v.rule.to_layer}): "
                    f"{_edge_text(edge)}"
                ),
            )
        )
    return StrictVerdict(
        baseline=baseline_label,
        findings=tuple(findings),
        carried_cycles=carried_cycles,
        carried_violations=carried_violations,
    )


def _cycle_detail(
    cycle: Cycle, seen: set[str], old_cycles: list[set[str]], edges: tuple[StrictEdge, ...]
) -> str:
    # A grown legacy tangle has hundreds of members; listing them buries the
    # cause. The finding's `modules` carries the full list either way.
    if len(cycle.modules) <= _MAX_EDGES_SHOWN:
        members = ", ".join(sorted(cycle.modules))
    else:
        members = f"{len(cycle.modules)} modules"
    if not seen:
        why = "a cycle among modules the baseline never saw"
    elif sum(1 for old in old_cycles if seen & old) > 1:
        why = "it merges cycles the baseline kept separate"
    else:
        outside = sorted(m for m in seen if not any(m in old for old in old_cycles))
        pulled = (
            ", ".join(outside)
            if len(outside) <= _MAX_EDGES_SHOWN
            else f"{len(outside)} acyclic modules"
        )
        why = f"it pulls {pulled} into a cycle" if outside else "a new cycle"
    shown = "; ".join(_edge_text(e) for e in edges[:_MAX_EDGES_SHOWN])
    more = f"; +{len(edges) - _MAX_EDGES_SHOWN} more" if len(edges) > _MAX_EDGES_SHOWN else ""
    return f"new import cycle ({why}): {members}. Closing edge(s): {shown}{more}"


def _edge_text(edge: StrictEdge) -> str:
    where = f" at {', '.join(edge.locations)}" if edge.locations else ""
    return f"{edge.source} -> {edge.target}{where}"

def _violation_key(v: Violation) -> tuple[str, str, str, str]:
    return (v.rule.from_layer, v.rule.to_layer, v.source, v.target)


class RulesFingerprint(BaseModel):
    """Canonical archy.yaml rules a findings-only baseline commits.

    Lists are sorted and de-duplicated so two equivalent configs write the
    same bytes. `required` entries are `(source, must_reach, within)` and
    omit `reason`, which does not change what the rule covers.
    """

    model_config = ConfigDict(frozen=True)

    forbid: tuple[tuple[str, str], ...] = ()
    layers: tuple[tuple[str, tuple[str, ...]], ...] = ()
    required: tuple[tuple[str, str, str | None], ...] = ()
    exclude: tuple[str, ...] = ()
    roots: tuple[str, ...] = ()

    @classmethod
    def canonical(
        cls,
        *,
        forbid: Iterable[tuple[str, str]] = (),
        layers: Iterable[tuple[str, Iterable[str]]] = (),
        required: Iterable[tuple[str, str, str | None]] = (),
        exclude: Iterable[str] = (),
        roots: Iterable[str] = (),
    ) -> RulesFingerprint:
        merged: dict[str, set[str]] = {}
        for name, patterns in layers:
            merged.setdefault(name, set()).update(patterns)
        return cls(
            forbid=tuple(sorted(set(forbid))),
            layers=tuple((name, tuple(sorted(pats))) for name, pats in sorted(merged.items())),
            required=tuple(sorted(set(required), key=_required_key)),
            exclude=tuple(sorted(set(exclude))),
            roots=tuple(sorted(set(roots))),
        )


def weakened_rules(
    baseline: RulesFingerprint, current: RulesFingerprint, *, since: str
) -> tuple[str, ...]:
    """Rules `current` dropped or made weaker than `baseline`.

    An added forbid, layer, required contract, or root is not a weakening.
    A wider layer pattern or required `source` is not one either. A wider
    `must_reach` is, because more modules then count as satisfying it. An
    added `exclude` entry is too, because it drops directories out of the scan.
    """
    notes: list[str] = []
    current_forbid = set(current.forbid)
    for src, dst in baseline.forbid:
        if (src, dst) not in current_forbid:
            notes.append(f"forbid {src} -> {dst} removed since {since}")
    current_layers = dict(current.layers)
    for name, patterns in baseline.layers:
        if name not in current_layers:
            notes.append(f"layer {name} removed since {since}")
            continue
        for pattern in patterns:
            if not any(_pattern_covers(wider, pattern) for wider in current_layers[name]):
                notes.append(f"layer {name} pattern {pattern} narrowed since {since}")
    current_required = current.required
    for contract in baseline.required:
        if any(_required_covers(other, contract) for other in current_required):
            continue
        source, must, within = contract
        scope = f" within {within}" if within is not None else ""
        notes.append(f"required {source}{scope} must reach {must} removed since {since}")
    baseline_exclude = set(baseline.exclude)
    for name in current.exclude:
        if name not in baseline_exclude:
            notes.append(f"exclude {name} added since {since}")
    current_roots = set(current.roots)
    for name in baseline.roots:
        if name not in current_roots:
            notes.append(f"root {name} removed since {since}")
    return tuple(sorted(notes))


def _required_key(contract: tuple[str, str, str | None]) -> tuple[str, str, bool, str]:
    source, must, within = contract
    return (source, must, within is None, within or "")


def _required_covers(
    current: tuple[str, str, str | None], baseline: tuple[str, str, str | None]
) -> bool:
    """True when `current` obliges at least what `baseline` did.

    A wider source or `within` obliges more modules. A narrower `must_reach`
