    else:
        current = root.resolve()
    user_ignored = ignored - DEFAULT_IGNORED_DIRS
    for part in rel.parts[:-1]:
        current = None if current is None else current / part
        if part in HARD_IGNORED_DIRS or part in user_ignored:
            return True
        if part in SOFT_IGNORED_DIRS and (
            current is None or not (current / "__init__.py").is_file()
        ):
            return True
    return False
def _build_reexport_maps(
    modules: list[Module],
    parse_results: dict[str, ParseResult],
    internal_qualnames: set[str],
) -> dict[str, dict[str, str]]:
    # Re-exports live in package __init__.py files. For each `from .x import Foo`
    # (or absolute self-reference), record `{local_name: source_qualname}` so the
    # consumer-side resolver can route `from pkg import Foo` to `pkg.x` instead
    # of falling back to `pkg`.
