        if not m.is_package:
            continue
        result = parse_results.get(m.qualname)
        if result is None:
            continue
        pkg_map: dict[str, str] = {}
        for ref in result.imports:
            source = _reexport_source(ref, m, internal_qualnames)
            if source is None:
